def lire_position(valeurs, i):
    if i >= 0 and i < len(valeurs):
        return valeurs[i]
    return None

def dernier_ou_none(valeurs):
    if len(valeurs) == 0:
        return None
    return valeurs[-1]

def moyenne_ou_none(valeurs):
    if len(valeurs) == 0:
        return None
    total = 0
    for valeur in valeurs:
        total = total + valeur
    return total / len(valeurs)
